# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:00-17:15")]
        self.assertEqual(round_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest_step(self):
        spans = [parse_span("08:53-17:08")]
        self.assertEqual(round_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        spans = [parse_span("09:15-10:45")]
        self.assertEqual(round_spans(spans, 30), ["09:30-11:00 (1h 30m)"])

    def test_one_label_per_span_in_order(self):
        spans = [Span(600, 660), Span(60, 120)]
        self.assertEqual(
            round_spans(spans, 30),
            ["10:00-11:00 (1h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_end_of_day_stays_valid(self):
        spans = [parse_span("22:00-23:58")]
        self.assertEqual(round_spans(spans, 5), ["22:00-24:00 (2h 0m)"])

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_tiny_span_collapses_to_zero_length(self):
        spans = [parse_span("09:02-09:05")]
        self.assertEqual(round_spans(spans, 15), ["09:00-09:00 (0h 0m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            round_spans([], 0)

    def test_valid_steps_accepted(self):
        for step in (1, 2, 3, 5, 10, 12, 15, 20, 30, 60):
            self.assertEqual(len(round_spans([Span(0, 60)], step)), 1)
